const payload = $input.first().json;
const error = payload.error || {};
const transaction = payload.transaction || {};
const trace = payload.trace || {};

function classifyError(error_obj) {
  const code = error_obj.code || 'UNKNOWN_ERROR';
  const category = error_obj.category || 'unknown';

  const error_classes = {
    'PRETRANSACTION_DATA_INCONSISTENT': { class: 'validation', severity: 'critical', retryable: false },
    'INVOICING_CONFIGURATION_INCOMPLETE': { class: 'configuration', severity: 'high', retryable: false },
    'FULFILLMENT_CONFIGURATION_INCOMPLETE': { class: 'configuration', severity: 'high', retryable: false },
    'TRANSACTION_NOT_READY_FOR_COMPLETION': { class: 'business_rule', severity: 'high', retryable: false },
    'PAYMENT_PROCESSING_FAILED': { class: 'external_service', severity: 'critical', retryable: true },
    'ORDER_CREATION_FAILED': { class: 'external_service', severity: 'high', retryable: true },
    'INVOICE_CREATION_FAILED': { class: 'external_service', severity: 'medium', retryable: true },
    'SHIPMENT_CREATION_FAILED': { class: 'external_service', severity: 'medium', retryable: true },
    'DATABASE_CONNECTION_ERROR': { class: 'infrastructure', severity: 'critical', retryable: true },
    'TIMEOUT_ERROR': { class: 'infrastructure', severity: 'medium', retryable: true },
    'INVALID_CONFIGURATION': { class: 'configuration', severity: 'critical', retryable: false },
    'AUTHENTICATION_FAILED': { class: 'security', severity: 'critical', retryable: false },
    'DUPLICATE_OPERATION': { class: 'idempotency', severity: 'medium', retryable: false }
  };

  return error_classes[code] || { class: category, severity: 'unknown', retryable: true };
}

function determineRecoveryStrategy(classification, error_obj) {
  const strategy = {
    action: 'none',
    retry_count: 0,
    retry_delay_seconds: 0,
    escalate_to_human: false,
    rollback_required: false,
    webhook_notification: true
  };

  if (classification.retryable && error_obj.retryable !== false) {
    if (classification.class === 'external_service') {
      strategy.action = 'retry';
      strategy.retry_count = 3;
      strategy.retry_delay_seconds = 60;
    } else if (classification.class === 'infrastructure') {
      strategy.action = 'retry';
      strategy.retry_count = 5;
      strategy.retry_delay_seconds = 30;
    }
  }

  if (classification.severity === 'critical' || classification.class === 'validation') {
    strategy.escalate_to_human = true;
  }

  if (classification.class === 'external_service' && !classification.retryable) {
    strategy.escalate_to_human = true;
  }

  return strategy;
}

function buildErrorNotification(error_obj, classification, strategy) {
  const now = new Date();

  return {
    error_id: `err_${transaction.id}_${now.getTime()}`,
    timestamp: now.toISOString(),
    transaction_id: transaction.id,
    error: {
      code: error_obj.code,
      category: error_obj.category,
      message: error_obj.message,
      details: error_obj.details || {}
    },
    classification: {
      error_class: classification.class,
      severity: classification.severity,
      retryable: classification.retryable
    },
    recovery: strategy,
    trace: {
      trace_id: trace.trace_id,
      request_id: trace.request_id,
      originating_workflow: trace.workflow,
      originating_stage: trace.stage
    }
  };
}

const classification = classifyError(error);
const strategy = determineRecoveryStrategy(classification, error);
const notification = buildErrorNotification(error, classification, strategy);

let next_action = 'handle_error';
let new_status = 'failed';

if (strategy.escalate_to_human) {
  next_action = 'handoff_to_human';
  new_status = 'escalated';
} else if (strategy.action === 'retry') {
  next_action = 'retry_operation';
  new_status = transaction.status || 'error_retry_pending';
} else {
  new_status = 'failed';
}

return [{
  json: {
    result: {
      success: false,
      outcome: 'error_handled'
    },
    transaction: {
      transaction_id: transaction.id,
      previous_status: transaction.status,
      current_status: new_status,
      sub_status: null,
      next_action: next_action
    },
    route: {
      selected_flow: 'DALIA_M5_Commerce_Orchestrator',
      effective_action: 'handle_error',
      reason: `error_${classification.class}_${classification.severity}`
    },
    response: {
      message_required: strategy.escalate_to_human,
      message_type: strategy.escalate_to_human ? 'error_escalation' : null,
      reply_text: strategy.escalate_to_human ? `Se ha encontrado un error en tu compra y será revisada por nuestro equipo. Código: ${error.code}` : null,
      requested_fields: []
    },
    data: {
      error_handling: notification
    },
    error: null,
    trace: {
      trace_id: trace.trace_id || null,
      request_id: trace.request_id || null,
      workflow: 'DALIA_M5_07_Error_Handler',
      stage: 'error_classified_and_handled',
      processed_at: new Date().toISOString()
    }
  }
}];
